/* M01 — setup, private handover, turn control. */
(() => {
  const {$,esc,game:g,on}=LB;
  LB.modules.lobby=()=>{
    $('#lobby-module').innerHTML=`<div class="game-welcome" data-module="01"><div><span class="module-label">M01 · SETUP & TURNS</span><span class="stamp">JOIN THE FLOCK</span><h2>Big news.<br>Your best case.</h2><p>Gather your flock. Find clues. Win with evidence!</p><img src="assets/pip-sheep.svg" alt="Pip the sheep detective" class="welcome-pip"><div class="welcome-chips"><span>2–6 players</span><span>One shared device</span><span>No timer</span></div></div><form id="setup-form" class="setup-card"><h3>Who’s playing?</h3><div class="setup-options"><label>Players<select id="player-count">${[2,3,4,5,6].map(n=>`<option value="${n}">${n} players</option>`).join('')}</select></label><label>Demo finish<select id="match-target"><option value="3">First to 3 round wins</option><option value="5">First to 5 round wins</option></select></label></div><div id="player-fields"></div><button class="button primary full" type="submit">Deal the cards! →</button><button type="button" class="button full" id="resume-game" hidden>Back to our game</button><p class="support-note">Use nicknames. Pass the device when it’s someone else’s turn.</p></form></div><div class="quick-steps"><span><b>1</b> Build a case</span><span><b>2</b> Drop together</span><span><b>3</b> Count the clues</span></div><details class="adult-notes"><summary>About this demo & rule choices</summary><p>The setup, turn choices, shared drop, evidence values and round ties follow your two rule photos. All card text is original sample content. The three action effects are labeled samples, as requested.</p><p>Demo choices where the photos are silent: one-device play; first to 3 or 5 round wins; first player rotates each round; new decks each round; no mid-round recycling; an empty draw pile means drop; an empty case scores zero. Players agree which evidence counts. Equal highest totals—including zero—tie. This is not an official digital edition.</p><a href="wireframe.html">Four-member wireframe and plan →</a></details>`;
    function fields(){const old=Array.from(document.querySelectorAll('[data-player-name]')).map(e=>e.value);$('#player-fields').innerHTML=Array.from({length:Number($('#player-count').value)},(_,i)=>`<label class="player-label"><span class="player-dot dot-${i}">${i+1}</span><span class="sr-only">Player ${i+1} nickname</span><input data-player-name maxlength="20" required value="${esc(old[i]||['Alex','Sam','Jo','Lee','Robin','Kit'][i])}" autocomplete="off"></label>`).join('');}
    fields();$('#player-count').onchange=fields;
    $('#setup-form').onsubmit=e=>{e.preventDefault();const names=Array.from(document.querySelectorAll('[data-player-name]')).map(x=>x.value.trim());const start=()=>LB.run(()=>g.start(names,Number($('#match-target').value)),'Cards dealt! Pass to '+names[0]+'.');if(g.phase!=='lobby')LB.ask({title:'Start a new game?',text:'This clears the current hands and scores.',confirm:'New game',action:start});else start();};
    $('#resume-game').onclick=()=>LB.refresh();on('game:changed',render);render();
  };
  function render(){
    $('#resume-game').hidden=g.phase==='lobby';
    if(g.phase==='lobby'){$('#round-bar').innerHTML='';$('#handoff').hidden=true;return;}
    const hidden=g.phase==='handoff';$('#handoff').hidden=!hidden;$('.play-grid').hidden=hidden;
    $('#round-bar').innerHTML=`<div class="game-turnbar" data-module="01"><span class="module-label">M01 · TURNS</span><div><span class="eyebrow">ROUND ${g.round}</span><strong>${hidden?'Pass the device':g.phase==='drop'?'Everyone drops!':g.privatePhase?esc(g.player.name)+'’s turn':'Compare your cases'}</strong></div><div class="score-pills" aria-label="Round wins">${g.players.map(p=>`<span class="score-pill ${p.id===g.active?'current':''}"><span class="player-dot dot-${p.id}">${p.id+1}</span>${esc(p.name)} <b>${p.score}</b></span>`).join('')}</div>${g.privatePhase?'<button class="button small" id="hide-hand">Hide my hand</button>':''}</div>`;
    if($('#hide-hand')){
      $('#hide-hand').onclick=()=>LB.run(()=>g.hide(),'Hand hidden.');
      const jump=document.createElement('button');jump.className='button small';jump.textContent='My cards ↓';jump.id='jump-hand';
      jump.onclick=()=>{const heading=$('#evidence-module h2');if(heading){heading.tabIndex=-1;heading.scrollIntoView({block:'start'});heading.focus({preventScroll:true});}};
      $('#hide-hand').before(jump);
    }
    if(hidden){$('#handoff').innerHTML=`<div class="handoff-card"><img src="assets/pip-sheep.svg" alt="" class="handoff-pip"><span class="stamp">NO PEEKING!</span><h2>Over to ${esc(g.player.name)}.</h2><p>${g.resumePhase==='drop'?'Someone dropped! Make your case.':'Your cards are tucked away.'}</p><button class="button primary" id="reveal-hand">I’m ${esc(g.player.name)} · show my hand</button><small>Other players: look away.</small></div>`;$('#reveal-hand').onclick=()=>LB.run(()=>g.reveal(),g.resumePhase==='drop'?'Choose one side and drop your evidence.':'Play an action if you like, then draw or drop.');}
  }
})();
